import{_ as r,H as n,f as o,i as e}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"06｜了解项目的八步心法：从 README 到核心链路","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么要一套“心法”","slug":"为什么要一套-心法","link":"#为什么要一套-心法","children":[]},{"level":2,"title":"八步心法","slug":"八步心法","link":"#八步心法","children":[]},{"level":2,"title":"三个原则让心法落地","slug":"三个原则让心法落地","link":"#三个原则让心法落地","children":[{"level":3,"title":"第一个原则：螺旋不是线性","slug":"第一个原则-螺旋不是线性","link":"#第一个原则-螺旋不是线性","children":[]},{"level":3,"title":"第二个原则：沉淀文档，不是留在脑子里","slug":"第二个原则-沉淀文档-不是留在脑子里","link":"#第二个原则-沉淀文档-不是留在脑子里","children":[]},{"level":3,"title":"第三个原则：建立锚点，不是读懂","slug":"第三个原则-建立锚点-不是读懂","link":"#第三个原则-建立锚点-不是读懂","children":[]}]},{"level":2,"title":"接下来六讲要做什么","slug":"接下来六讲要做什么","link":"#接下来六讲要做什么","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/06｜了解项目的八步心法：从README到核心链路.md","filePath":"ClaudeCode企业级老项目改造实战/06｜了解项目的八步心法：从README到核心链路.md","lastUpdated":1779815445000}'),a={name:"ClaudeCode企业级老项目改造实战/06｜了解项目的八步心法：从README到核心链路.md"};function s(p,t,l,i,g,d){return n(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="_06-了解项目的八步心法-从-readme-到核心链路" tabindex="-1">06｜了解项目的八步心法：从 README 到核心链路 <a class="header-anchor" href="#_06-了解项目的八步心法-从-readme-到核心链路" aria-label="Permalink to &quot;06｜了解项目的八步心法：从 README 到核心链路&quot;">​</a></h1><p>你好，我是 Robert。</p><p>从这一讲开始，我们真正上手开始改造。这部分的核心议题叫做“了解项目”。在标准的流程中或者在我看来， <strong>一个老项目到手，不管你准备改什么，第一件事永远是先把它摸清楚。这一步没走扎实，后面所有动作都是瞎动</strong>。</p><p>第二部分的六讲围绕一件事： <strong>怎么用 Claude Code 高效地摸清一个陌生老项目</strong>。这一讲是开篇，给你一套心法，接下来每一讲对应心法里的一个具体动作。</p><h2 id="为什么要一套-心法" tabindex="-1">为什么要一套“心法” <a class="header-anchor" href="#为什么要一套-心法" aria-label="Permalink to &quot;为什么要一套“心法”&quot;">​</a></h2><p>你可能会问：了解项目不就是读 readme、看代码、搭环境这些事嘛，需要什么“心法”？ <strong>正是因为这些事太“日常”，反而容易走偏</strong>。我见过的两种典型失败模式。</p><p><strong>第一种，从头到尾读代码</strong>。</p><p>项目拿到手，打开 IDE，从 controller 开始，一个方法一个方法读下去。读到第三天还没读完 service 层，进度条只往前推了 10%。老板在群里问“项目看得怎么样了”，你说“还在看”。</p><p>这种方式的问题不是慢，是 <strong>读过的东西一会就忘</strong>。项目没改，你只是在通读，没有锚点，没有目标。一周之后再回来，代码好像又变陌生了。</p><p><strong>第二种，直接让 AI 干</strong>。</p><p>反过来，有人信奉“AI 时代不需要自己读代码”。项目拿到手直接打开 Claude Code：“帮我总结一下这个项目是做什么的”，AI 给一段漂亮的总结；“帮我找出改造点”，AI 给一个 todo list；“帮我写改造方案”，AI 给一个方案。照着改，上线，出事。</p><p>这种方式的问题更隐蔽： <strong>你看起来很快，但其实什么都不懂</strong>。AI 的总结是基于它看到的代码给的，它看不到的那些历史、对接方、隐性约定，你也没去补。你以为自己上手了，其实还在地面。</p><p>这两种失败的共同原因是同一个： <strong>没有一套“最小完备的锚点清单”</strong>。</p><p>从头到尾读是无重点，让 AI 全盘托管是无参与。你需要一个清晰的骨架，知道要搞清楚哪些事、不搞清楚哪些事、哪些事 AI 做、哪些事必须自己做。这就是心法。</p><h2 id="八步心法" tabindex="-1">八步心法 <a class="header-anchor" href="#八步心法" aria-label="Permalink to &quot;八步心法&quot;">​</a></h2><p>把“了解老项目”这件事拆开，我归纳出八步。这八步不是我发明的，是任何一个接过老项目的工程师或多或少都在走的路径，只是没有写下来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975378/7d2b28b04605e821b866ab60ec49d93c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/975378/7d2b28b04605e821b866ab60ec49d93c.png" alt=""></a></p><p>这八步我一件一件跟你说。</p><p><strong>第一步，读 README 和根目录的文档</strong>。</p><p>打开项目先看 README，再看 docs 目录。别嫌弃 README 写得简陋，能看多少算多少。这一步不是为了“懂”，是为了建立一个 <strong>最粗的轮廓</strong>：这个项目做什么的、跑在什么环境、有哪些核心概念。</p><p><strong>第二步，扫项目结构</strong>。</p><p>把仓库 clone 下来，看目录和包组织。Java 项目看 pom.xml 的 module 划分，Go 项目看 cmd 和 internal，TypeScript 项目看 packages 或 src 一级目录。</p><p>这一步的核心是建立一张 <strong>模块地图</strong>：项目分几块、每块大概干什么、哪些是核心、哪些是边缘。不看代码细节，只看结构。</p><p><strong>第三步，找到核心入口</strong>。</p><p>知道模块地图之后，找具体的入口。HTTP 服务找 controller 和 main 函数；定时任务找调度注册处；消息消费找 consumer 或 listener。</p><p>入口很重要。它是从用户到代码的 <strong>第一个接触点</strong>，代码所有的主流程都从入口出发。找到入口你就找到了地图上的坐标原点。</p><p><strong>第四步，画出项目全景</strong>。</p><p>到这一步你对项目有了基础认知，但散碎。第四步要把散碎的认知 <strong>拼成一张图</strong>：架构图、模块依赖图、核心数据流图。</p><p>这张图不需要精细，粗糙的手绘都行。关键是画出来，不要只停在脑子里。一画你就会发现哪里想不清楚、哪里的关系没理顺。这一步是 07 和 08 讲的主题。</p><p><strong>第五步，梳理接口和数据模型</strong>。</p><p>有了全景之后深入一层：项目对外暴露什么接口？内部核心数据结构是什么？</p><p>接口是项目的“对外契约”，数据模型是项目的“内部骨骼”。把这两样梳理清楚，你就掌握了这个项目的 <strong>输入输出</strong> 和 <strong>核心抽象</strong>。这一步是 09 讲的主题。</p><p><strong>第六步，搭起环境跑起来</strong>。</p><p>理论上你已经对项目有了相当的认知，但 <strong>真正的检验是跑起来</strong>。</p><p>搭环境经常比想象的难。依赖的数据库版本、中间件、内部服务、环境变量，每一个都可能卡你半天。跑不起来是正常的，跑起来的那一刻你对项目会有质的认知飞跃：能打断点、能看日志、能复现问题。这一步跨到第三部分 13 讲详细展开。</p><p><strong>第七步，带着需求深挖代码</strong>。</p><p>跑起来之后，不要继续通读。开始带着具体需求深挖：我要改哪个模块？我要加什么功能？带着这个问题回到代码里，沿着调用链路深挖。</p><p>这一步读的代码是有目标的。每一处都带着问题：这里为什么这么写？这段逻辑会被谁调用？改了会影响哪里？ <strong>有目标的读胜过无目标的读一百倍</strong>。</p><p><strong>第八步，沉淀成 AI 能读的文档</strong>。</p><p>前面七步做完，你脑子里清楚了，但这不够。你得把这些理解沉淀到文档里，让 AI 也能读到。</p><p>具体就是两份东西：CLAUDE.md（项目特定的上下文备忘录）和 SKILL.md（可复用的操作模板）。前七步的产出一股脑写进这两份文档里。这一步是 10 和 11 讲的主题。</p><p>八步合起来干一件事： <strong>把你脑子里的理解，变成 AI 也能看见的资产</strong>。</p><h2 id="三个原则让心法落地" tabindex="-1">三个原则让心法落地 <a class="header-anchor" href="#三个原则让心法落地" aria-label="Permalink to &quot;三个原则让心法落地&quot;">​</a></h2><p>光有八步清单不够，还有三个原则决定你能不能用好它。</p><h3 id="第一个原则-螺旋不是线性" tabindex="-1">第一个原则：螺旋不是线性 <a class="header-anchor" href="#第一个原则-螺旋不是线性" aria-label="Permalink to &quot;第一个原则：螺旋不是线性&quot;">​</a></h3><p>八步是清单，不是顺序流水。真实工作里，你读 README 的时候顺手扫了项目结构，搭环境的时候发现了一个接口要回去查代码，画全景的时候意识到核心入口漏了一个。</p><p><strong>这些来回是正常的，甚至是必要的</strong>。八步是一个锚点清单，告诉你“这几件事都要做”，不是必须按 1 到 8 的顺序做。</p><p>你可以在第四步“画全景”画到一半发现自己对某个模块理解不够，回第二步重看结构；你可以在第六步“跑起来”的时候发现一个没见过的接口，回第五步补接口清单。这些都没问题。 <strong>重点是八步最后都要走到，不是次序</strong>。</p><h3 id="第二个原则-沉淀文档-不是留在脑子里" tabindex="-1">第二个原则：沉淀文档，不是留在脑子里 <a class="header-anchor" href="#第二个原则-沉淀文档-不是留在脑子里" aria-label="Permalink to &quot;第二个原则：沉淀文档，不是留在脑子里&quot;">​</a></h3><p>我反复强调过这件事。人的脑子有极限，今天搞懂的东西下周可能就忘一半。更关键的是， <strong>留在你脑子里的东西 AI 读不到</strong>。每走完一步，问自己一个问题： <strong>这一步的产出我写到哪里了？</strong></p><p>第一步读完 README，有没有把关键点抄到一份笔记里？第三步找到核心入口，有没有记在项目 map 的某一行？第五步梳理出接口清单，有没有存成一份可查的 markdown？</p><p>没沉淀等于没做。这也是为什么第八步专门拎出来讲“沉淀成 AI 能读的文档”。前七步做了一堆，最后一步是把它们固化下来。 <strong>前七步是理解，第八步是资产</strong>。两件不同的事。</p><h3 id="第三个原则-建立锚点-不是读懂" tabindex="-1">第三个原则：建立锚点，不是读懂 <a class="header-anchor" href="#第三个原则-建立锚点-不是读懂" aria-label="Permalink to &quot;第三个原则：建立锚点，不是读懂&quot;">​</a></h3><p>最后一个原则最反直觉。很多人接老项目第一反应是“我要把这个项目读懂”，然后陷进代码里出不来。 <strong>你的目标不是读懂，是建立锚点</strong>。</p><p>什么叫锚点？ <strong>是你要改这个项目时能抓住的把手</strong>。知道核心链路从哪到哪、知道哪些模块是高风险、知道哪些接口是对外契约、知道历史上有哪些坑。</p><p>有了这些锚点，你就算还没读懂整个项目，也能安全地改造。真要改某个具体模块，到时候再深挖那个模块就行。</p><p>老项目改造里有一个残酷的真相： <strong>你永远不会真的读懂一个老项目</strong>。代码几万几十万行，写它的人换过好几拨，历史细节没人记得全。你要做的是 <strong>建立“足以推进改造”的理解</strong>，不是“完整无缺的理解”。</p><p>八步心法就是在帮你建立这份“足以推进改造”的最小理解。</p><h2 id="接下来六讲要做什么" tabindex="-1">接下来六讲要做什么 <a class="header-anchor" href="#接下来六讲要做什么" aria-label="Permalink to &quot;接下来六讲要做什么&quot;">​</a></h2><p>说完心法，说项目。从 07 讲开始，我会带你把这八步心法在一个具体项目上走一遍。这个项目叫 <strong>Spring AI Alibaba Admin</strong>。</p><p>它是阿里巴巴官方开源的 Agent Studio 管理平台，在 spring-ai-alibaba 这个主仓库下面作为子项目。定位是 AI Agent 的一站式开发平台，支持 Prompt 管理、Dataset 管理、Evaluator、实验、Observability、多模型配置。启动后是一个跑在 8080 端口的 Web 服务，有前端管理界面、有一套 REST API、有 MySQL 和 Nacos 作为依赖。Apache 2.0 协议，Java + React 前后端分离。</p><p><strong>为什么选它当主线？</strong> 三个理由。</p><ol><li><p><strong>它长的和你每天打交道的那种老项目很像</strong>。在公司维护的项目大概率就是这种形态：一个 HTTP 服务、Spring Boot，连着 MySQL，对外提供一堆 REST 接口，前端是独立的管理界面，可能还集成了 Nacos 做配置中心、OpenTelemetry 做链路追踪。一个标准的企业级微服务。Spring AI Alibaba Admin 就是这个样子。它不是什么简化的 demo 项目，是一个 <strong>真实形态的、完整的企业级微服务</strong>。多模块 Maven（4 个 server 子模块 + frontend）、前后端分离、接数据库、接中间件、有 Actuator。你在这个项目上练出的方法论，能 <strong>一比一迁移到公司那个跑了几年的老系统上</strong>。这是拿它当主线最根本的理由。</p></li><li><p><strong>AI 方向贴合</strong>。你作为一个 AI 时代的工程师，改 AI 相关的项目有代入感。Prompt 管理、Evaluator、Trace 观测这些功能，你日常在用，改起来能快速进入状态。</p></li><li><p><strong>开源相对活跃、背书强</strong>。阿里巴巴官方维护，Apache 2.0。你学完课程可以真实地给它提 issue、提 PR。Google 一下能搜到一堆中文资料，有不懂的地方自己能深挖。这种活跃的开源项目做教学材料最稳，不会出现“项目失联”或者“文档过时到没法用”的情况。</p></li></ol><p>接下来六讲，每一讲要做什么事？</p><ul><li><p><strong>07 讲：</strong> 在讲怎么画之前，得先让 Claude Code 真的能画图。你会拿到一个装好画图能力的 Claude Code，以及一张“什么场景用什么图”的心智地图。</p></li><li><p><strong>08 讲</strong>：让 AI 画出 Spring AI Alibaba Admin 的全景（对应八步心法的第四步）。你会拿到一张架构图、一张模块依赖图、一张核心数据流图。</p></li><li><p><strong>09 讲</strong>：梳理 Spring AI Alibaba Admin 的接口和数据模型（对应第五步）。你会得到一份完整的 REST 接口清单和核心数据结构说明。</p></li><li><p><strong>10 讲</strong>：写 CLAUDE.md（对应第八步的一半）。把前面的产出沉淀成 AI 协作的项目备忘录。</p></li><li><p><strong>11 讲</strong>：搭 SKILL.md 和文档体系（对应第八步的另一半）。把可复用的操作模板固化下来。</p></li><li><p><strong>12 讲</strong>：实操。把 06 到 11 讲的所有东西在 Spring AI Alibaba Admin 上完整跑一遍，作为第二部分的收尾。</p></li></ul><p>六讲下来，你会 <strong>拿到一份摸透了的 Spring AI Alibaba Admin</strong>，为第三部分的编译运行和护栏打基础，再为第四部分的真实改造做最终铺垫。</p><p>然后你就可以拿着这套体系套用到每一个老项目中了。 <strong>提示词都不用改。</strong> 这就是这门课想同时交给你的：“技”和“道”。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲给了你一套了解老项目的 <strong>八步心法</strong>：读 README、扫项目结构、找核心入口、画项目全景、梳理接口和数据模型、搭环境跑起来、带需求深挖代码、沉淀成 AI 能读的文档。</p><p>三个原则让心法落地： <strong>螺旋不是线性</strong>、 <strong>沉淀文档不是留在脑子里</strong>、 <strong>建立锚点不是读懂</strong>。</p><p>这一讲没有具体动手，是给你一个骨架。从 07 讲开始，每一讲你都会拿着 Claude Code 在 Spring AI Alibaba Admin 上干一件具体的事。干的这些事合起来，就是八步心法的完整落地。</p><p>老项目改造最难的第一步从来不是改，是摸清。摸清这件事过去靠工程师的经验和韧性，现在有 AI，但方法论不变，只是执行更快。</p><p>这门课教不了你把每一个项目都摸到完美，也不承诺你走完八步就万事大吉。 <strong>我能做的是把我自己多年接老项目的一套动作诚实地交给你</strong>，你拿去在自己的项目上走一走、改一改，走出属于你自己的节奏。熬过冷启动，后面全是复利。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>回想你最近接手的一个老项目，八步心法里哪几步你没走到或者走得不扎实？如果让你重来一次，你会补哪几步？</p></li><li><p>你手上现在正在维护的项目，如果让你给下一个接手的同事留一份 CLAUDE.md，你能写多少？写不出来的部分，是因为你自己也没搞清楚，还是因为没来得及沉淀？</p></li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>',76)])])}const c=r(a,[["render",s]]);export{h as __pageData,c as default};
